#!/usr/bin/env bash
# cli-dockerfile-test.sh: pf_cli_dockerfile (scripts/preflight/docker.sh) resolves a cli plugin's
# build targets through scripts/release/cli-targets.sh, so preflight builds what the release builds (D-0622).
# Cases: a v2-only manifest (compat keys generated by the pinned tool) resolves; a refused manifest, a tool that fails, split or numeric names, and an unsafe name are all rejected.
# Env: CLI_TARGETS_TOOL (built manifestv2migrate; unset builds the pinned one). Exit 0 all pass.
set -u
here=$(cd "$(dirname "$0")" && pwd)
repo=$(cd "$here/../.." && pwd)
. "$repo/scripts/preflight/docker.sh"
work=$(mktemp -d); trap 'rm -rf "$work"' EXIT
if [ -z "${CLI_TARGETS_TOOL:-}" ]; then
  . "$repo/scripts/conformance/lib.sh"
  CLI_TARGETS_TOOL=$(cli_tool manifestv2migrate) || { echo "cannot build manifestv2migrate" >&2; exit 1; }
fi
real=$CLI_TARGETS_TOOL
fail=0
ok() { echo "ok: $1"; }
bad() { echo "FAIL: $1" >&2; fail=1; }

# plugin DIR MANIFEST-JSON: a tree with go.mod, a vendor dir and cmd/<command>/.
plugin() {
  mkdir -p "$1/cmd/$3"; printf 'module x\n\ngo 1.22\n' >"$1/go.mod"; mkdir "$1/vendor"
  printf '%s\n' "$2" >"$1/plugin.json"
}
# stub OUT-BODY EXIT: a CLI_TARGETS_TOOL that prints OUT-BODY and exits EXIT.
stub() { printf '#!/bin/sh\nprintf "%%b" '"'%s'"'\nexit %s\n' "$1" "$2" >"$work/stub.sh"; chmod +x "$work/stub.sh"; }

# 1. v2 manifest with only the commands block; the compat keys come from the pinned tool.
t="$work/v2"
plugin "$t" '{"manifest_version":2,"name":"foo","version":"1.0.0","description":"d","license":"free","category":"infrastructure","maturity":"implemented","service":{"kind":"cli"},"commands":{"binary":"nself-foo","command":"foo","summary":"s"}}' foo
"$real" -in "$t/plugin.json" -compat -write >/dev/null 2>&1
why=$(CLI_TARGETS_TOOL=$real pf_cli_dockerfile "$t" "$t/plugin.json" "$work/v2.df") && rc=0 || rc=$?
if [ "$rc" = 0 ] && grep -q -- '-o /out/nself-foo ./cmd/foo/$' "$work/v2.df"; then ok "v2-only manifest resolved"; else bad "v2 binary/command pair (rc=$rc: $why)"; fi

# 2. a manifest the tool refuses
t="$work/badjson"; mkdir -p "$t"; printf 'module x\n\ngo 1.22\n' >"$t/go.mod"; echo '{' >"$t/plugin.json"
why=$(CLI_TARGETS_TOOL=$real pf_cli_dockerfile "$t" "$t/plugin.json" "$work/bad.df") && bad "refused manifest accepted" || ok "refused manifest rejected: ${why%%$'\n'*}"

# 3. a tool that fails after printing a valid line (the exit status must be checked)
# The tree holds a manifest the old jq parsing accepted, so only the tool's answer can reject it.
t="$work/stubbed"; plugin "$t" "$(cat "$repo/tests/fixtures/manifest-v2-cli/plugin.json")" foo
stub 'nself-foo\tfoo\n' 1
why=$(CLI_TARGETS_TOOL=$work/stub.sh pf_cli_dockerfile "$t" "$t/plugin.json" "$work/s.df") && bad "tool failure ignored" || ok "tool failure rejected"

# 4. split, numeric, unsafe and empty names are never turned into a build
for case in 'nself-a\nb\tb\n:split name' 'nself-1\t1\n:numeric name' 'nself-foo\tfoo bar\n:space in name' 'nself-foo\t../x\n:path in name' 'nself-foo\tFoo\n:upper case name' 'nself-foo\n:no command column' ':no targets'; do
  stub "${case%%:*}" 0
  why=$(CLI_TARGETS_TOOL=$work/stub.sh pf_cli_dockerfile "$t" "$t/plugin.json" "$work/s.df") && bad "${case#*:} accepted" || ok "${case#*:} rejected"
done

exit $fail
